// ---- _shared/form-security.ts ----------------------------------------------------------------
/**
 * _shared/form-security.ts — server-side enforcement of form anti-abuse rules.
 *
 * This is the security boundary. The browser-side copy in
 * `apps/web/src/lib/form-security.ts` improves the respondent's experience by
 * failing fast, but every check that matters is repeated here, because a bot
 * posts to this endpoint directly and never runs the page's JavaScript.
 *
 * Challenge tokens are HMAC-SHA256 signed with FORM_CHALLENGE_SECRET so the
 * expected answer can travel through an untrusted client without being forged.
 */

const encoder = new TextEncoder();

type CaptchaProvider =
  | 'none'
  | 'smart_math'
  | 'proof_of_work'
  | 'turnstile'
  | 'hcaptcha'
  | 'recaptcha_v3';

type CaptchaConfig = {
  provider?: CaptchaProvider;
  trigger?: 'always' | 'suspicious';
  difficulty?: 'easy' | 'medium' | 'hard';
  site_key?: string;
  secret_variable?: string;
  score_threshold?: number;
  ttl_seconds?: number;
};

type BotProtectionConfig = {
  honeypot_enabled?: boolean;
  honeypot_field?: string;
  min_fill_seconds?: number;
  max_fill_seconds?: number;
  require_nonce?: boolean;
  rate_limit_per_hour?: number;
  rate_limit_per_day?: number;
  duplicate_window_minutes?: number;
  block_disposable_email?: boolean;
  enforce_origin?: boolean;
  blocked_ips?: string[];
};

type InputHardeningConfig = {
  strict_field_whitelist?: boolean;
  max_field_length?: number;
  max_payload_kb?: number;
  sanitize_html?: boolean;
  reject_control_chars?: boolean;
  injection_scan?: 'off' | 'flag' | 'block';
};

type FormSecurityConfig = {
  captcha?: CaptchaConfig;
  bot?: BotProtectionConfig;
  input?: InputHardeningConfig;
};

const DIFFICULTY_SPEC = {
  easy: { mathMax: 10, mathOps: 1, powBits: 12 },
  medium: { mathMax: 25, mathOps: 2, powBits: 16 },
  hard: { mathMax: 60, mathOps: 2, powBits: 20 },
} as const;

// -----------------------------------------------------------------------------
// Signed challenge tokens
// -----------------------------------------------------------------------------

function b64url(bytes: Uint8Array): string {
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function unb64url(value: string): Uint8Array {
  const padded = value.replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(padded + '='.repeat((4 - (padded.length % 4)) % 4));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function challengeSecret(): string {
  const secret = Deno.env.get('FORM_CHALLENGE_SECRET');
  if (!secret) {
    throw new Error(
      'FORM_CHALLENGE_SECRET is not set. Add it to the edge function secrets before enabling challenges.',
    );
  }
  return secret;
}

async function hmac(payload: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(challengeSecret()),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(payload));
  return b64url(new Uint8Array(sig));
}

/** Constant-time string comparison, so signature checks leak no timing signal. */
function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

type ChallengePayload = {
  /** Expected answer for smart_math, or the puzzle input for proof_of_work. */
  a: string;
  /** Required leading zero bits for proof_of_work. */
  b?: number;
  /** Form this challenge was issued for. */
  f: string;
  /** Expiry, epoch seconds. */
  e: number;
  /** Random unique id, used to burn the token after one use. */
  n: string;
};

async function signChallenge(payload: ChallengePayload): Promise<string> {
  const body = b64url(encoder.encode(JSON.stringify(payload)));
  return `${body}.${await hmac(body)}`;
}

async function verifyChallengeToken(
  token: string,
  formId: string,
): Promise<{ payload?: ChallengePayload; error?: string }> {
  const [body, sig] = token.split('.');
  if (!body || !sig) return { error: 'Malformed challenge token' };
  if (!timingSafeEqual(sig, await hmac(body))) return { error: 'Challenge signature is invalid' };

  let payload: ChallengePayload;
  try {
    payload = JSON.parse(new TextDecoder().decode(unb64url(body)));
  } catch {
    return { error: 'Malformed challenge token' };
  }

  if (payload.f !== formId) return { error: 'Challenge was issued for a different form' };
  if (payload.e < Math.floor(Date.now() / 1000)) return { error: 'Challenge expired — please retry' };
  return { payload };
}

/** Build a fresh challenge for the self-hosted providers. */
async function issueChallenge(
  provider: 'smart_math' | 'proof_of_work',
  formId: string,
  difficulty: 'easy' | 'medium' | 'hard' = 'medium',
  ttlSeconds = 600,
): Promise<{ token: string; question?: string; challenge?: string; bits?: number }> {
  const spec = DIFFICULTY_SPEC[difficulty];
  const exp = Math.floor(Date.now() / 1000) + ttlSeconds;
  const nonce = b64url(crypto.getRandomValues(new Uint8Array(12)));

  if (provider === 'proof_of_work') {
    const puzzle = b64url(crypto.getRandomValues(new Uint8Array(16)));
    const token = await signChallenge({ a: puzzle, b: spec.powBits, f: formId, e: exp, n: nonce });
    return { token, challenge: puzzle, bits: spec.powBits };
  }

  const rand = (max: number) => 1 + Math.floor(Math.random() * max);
  const x = rand(spec.mathMax);
  const y = rand(spec.mathMax);
  let question: string;
  let answer: number;

  if (spec.mathOps === 1) {
    question = `${x} + ${y}`;
    answer = x + y;
  } else {
    const z = rand(9);
    // Keep the result non-negative so the prompt stays friendly.
    if (x >= y) {
      question = `${x} - ${y} + ${z}`;
      answer = x - y + z;
    } else {
      question = `${x} + ${y} - ${z}`;
      answer = x + y - z;
    }
  }

  const token = await signChallenge({ a: String(answer), f: formId, e: exp, n: nonce });
  return { token, question: `${question} = ?` };
}

function leadingZeroBits(bytes: Uint8Array): number {
  let count = 0;
  for (const byte of bytes) {
    if (byte === 0) {
      count += 8;
      continue;
    }
    for (let bit = 7; bit >= 0; bit -= 1) {
      if ((byte >> bit) & 1) return count;
      count += 1;
    }
    return count;
  }
  return count;
}

// -----------------------------------------------------------------------------
// Hosted provider verification
// -----------------------------------------------------------------------------

const HOSTED_VERIFY_URL: Record<string, string> = {
  turnstile: 'https://challenges.cloudflare.com/turnstile/v0/siteverify',
  hcaptcha: 'https://api.hcaptcha.com/siteverify',
  recaptcha_v3: 'https://www.google.com/recaptcha/api/siteverify',
};

async function verifyHostedCaptcha(
  provider: 'turnstile' | 'hcaptcha' | 'recaptcha_v3',
  responseToken: string,
  secret: string,
  remoteIp?: string,
  scoreThreshold = 0.5,
): Promise<{ ok: boolean; error?: string }> {
  const params = new URLSearchParams({ secret, response: responseToken });
  if (remoteIp) params.set('remoteip', remoteIp);

  let result: { success?: boolean; score?: number; 'error-codes'?: string[] };
  try {
    const res = await fetch(HOSTED_VERIFY_URL[provider], {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: params.toString(),
    });
    result = await res.json();
  } catch {
    // Fail closed: an unreachable verifier must not become an open door.
    return { ok: false, error: 'Could not reach the CAPTCHA verifier' };
  }

  if (!result.success) {
    return { ok: false, error: `CAPTCHA verification failed (${(result['error-codes'] ?? []).join(', ') || 'rejected'})` };
  }
  if (provider === 'recaptcha_v3' && typeof result.score === 'number' && result.score < scoreThreshold) {
    return { ok: false, error: `Score ${result.score.toFixed(2)} is below the ${scoreThreshold} threshold` };
  }
  return { ok: true };
}

// -----------------------------------------------------------------------------
// Input hardening
// -----------------------------------------------------------------------------

const INJECTION_SIGNATURES: Array<{ name: string; pattern: RegExp }> = [
  { name: 'sql_union', pattern: /\bunion\b[\s\S]{0,40}\bselect\b/i },
  { name: 'sql_tautology', pattern: /(['"]\s*(or|and)\s*['"]?\d+['"]?\s*=\s*['"]?\d+)/i },
  { name: 'sql_comment_terminator', pattern: /(--|#|\/\*)\s*$/ },
  { name: 'sql_stacked', pattern: /;\s*(drop|delete|update|insert|alter|truncate)\s+/i },
  { name: 'script_tag', pattern: /<\s*script\b/i },
  { name: 'event_handler', pattern: /\bon(error|load|click|mouseover)\s*=/i },
  { name: 'js_uri', pattern: /javascript\s*:/i },
  { name: 'template_injection', pattern: /\{\{[\s\S]*?\}\}|\$\{[\s\S]*?\}/ },
  { name: 'path_traversal', pattern: /\.\.[/\\]{1,2}(etc|windows|proc)\b/i },
  { name: 'command_chain', pattern: /[;|&]{1,2}\s*(cat|curl|wget|nc|bash|sh|powershell)\s/i },
];

type SanitizeResult = {
  data: Record<string, unknown>;
  dropped: string[];
  findings: Array<{ field: string; signature: string }>;
  blocked?: string;
};

function sanitizeSubmission(
  data: Record<string, unknown>,
  allowedFields: string[],
  config: InputHardeningConfig = {},
): SanitizeResult {
  const {
    strict_field_whitelist = true,
    max_field_length = 5000,
    max_payload_kb = 256,
    sanitize_html = true,
    reject_control_chars = true,
    injection_scan = 'flag',
  } = config;

  const sizeKb = encoder.encode(JSON.stringify(data)).length / 1024;
  if (sizeKb > max_payload_kb) {
    return {
      data: {},
      dropped: [],
      findings: [],
      blocked: `Payload is ${sizeKb.toFixed(0)}KB, over the ${max_payload_kb}KB limit`,
    };
  }

  const allowed = new Set(allowedFields);
  const out: Record<string, unknown> = {};
  const dropped: string[] = [];

  for (const [key, value] of Object.entries(data)) {
    if (strict_field_whitelist && !allowed.has(key)) {
      dropped.push(key);
      continue;
    }
    if (typeof value !== 'string') {
      out[key] = value;
      continue;
    }
    let next = value;
    if (reject_control_chars) next = next.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
    if (sanitize_html) next = next.replace(/<[^>]*>/g, '').replace(/[<>]/g, '').trim();
    if (next.length > max_field_length) next = next.slice(0, max_field_length);
    out[key] = next;
  }

  const findings: Array<{ field: string; signature: string }> = [];
  if (injection_scan !== 'off') {
    for (const [field, value] of Object.entries(out)) {
      const text = typeof value === 'string' ? value : JSON.stringify(value ?? '');
      for (const { name, pattern } of INJECTION_SIGNATURES) {
        if (pattern.test(text)) findings.push({ field, signature: name });
      }
    }
  }

  const blocked =
    injection_scan === 'block' && findings.length > 0
      ? `Submission rejected: ${findings[0].signature} detected in "${findings[0].field}"`
      : undefined;

  return { data: out, dropped, findings, blocked };
}

const DISPOSABLE_EMAIL_DOMAINS = new Set([
  'mailinator.com',
  'guerrillamail.com',
  '10minutemail.com',
  'tempmail.com',
  'throwawaymail.com',
  'yopmail.com',
  'trashmail.com',
  'sharklasers.com',
  'getnada.com',
  'temp-mail.org',
  'fakeinbox.com',
  'dispostable.com',
]);

function isDisposableEmail(email: string): boolean {
  const domain = email.split('@')[1]?.toLowerCase().trim();
  return domain ? DISPOSABLE_EMAIL_DOMAINS.has(domain) : false;
}

function isOriginAllowed(origin: string | null, allowed: string[]): boolean {
  if (allowed.length === 0) return true;
  if (!origin) return false;
  let host: string;
  try {
    host = new URL(origin).hostname.toLowerCase();
  } catch {
    return false;
  }
  return allowed.some((entry) => {
    const clean = entry.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '');
    if (!clean) return false;
    if (clean.startsWith('*.')) return host === clean.slice(2) || host.endsWith(clean.slice(1));
    return host === clean;
  });
}

/** Stable hash of a payload, for duplicate detection. */
async function payloadFingerprint(data: Record<string, unknown>): Promise<string> {
  const canonical = JSON.stringify(data, Object.keys(data).sort());
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(canonical));
  return b64url(new Uint8Array(digest));
}

/** Best-effort client IP from the proxy headers Supabase sets. */
function clientIp(req: Request): string {
  const fwd = req.headers.get('x-forwarded-for');
  if (fwd) return fwd.split(',')[0].trim();
  return req.headers.get('cf-connecting-ip') ?? req.headers.get('x-real-ip') ?? 'unknown';
}

// ---- _shared/secret-box.ts -------------------------------------------------------------------
// Server-side secret sealing (Phase 0 · SEC-05/SEC-07).
//
// Seals tenant secrets (AI provider keys, global-variable secrets) with AES-256-GCM
// using ONE server-only master key: the edge-function secret MARBEE_SECRETS_KEY
// (32 random bytes, base64). The database only ever stores the sealed envelope:
//
//     mbs1.<base64 12-byte IV>.<base64 ciphertext+tag>
//
// The browser never sees the master key or the plaintext. Values written before this
// existed are plaintext ("legacy"); openSecret() still returns them so nothing breaks,
// and callers re-seal them on next use.
//
// Generate a key:  node -e "console.log(require('crypto').randomBytes(32).toString('base64'))"
// Set it:          Supabase Dashboard → Edge Functions → Secrets → MARBEE_SECRETS_KEY

const PREFIX = 'mbs1';
const enc = new TextEncoder();
const dec = new TextDecoder();

let cachedKey: CryptoKey | null = null;
let cachedFrom: string | null = null;

function b64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i += 1) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function unb64(s: string): Uint8Array<ArrayBuffer> {
  const bin = atob(s);
  const out = new Uint8Array(new ArrayBuffer(bin.length));
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function readMasterKey(): string {
  // deno-lint-ignore no-explicit-any
  const env = (globalThis as any).Deno?.env;
  const v = env?.get('MARBEE_SECRETS_KEY')?.trim();
  if (!v) throw new Error('Server misconfigured: MARBEE_SECRETS_KEY is not set');
  return v;
}

async function masterKey(): Promise<CryptoKey> {
  const material = readMasterKey();
  if (cachedKey && cachedFrom === material) return cachedKey;
  const raw = unb64(material);
  if (raw.length !== 32) throw new Error('MARBEE_SECRETS_KEY must be 32 bytes (base64)');
  cachedKey = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  cachedFrom = material;
  return cachedKey;
}

function isSealed(value: string | null | undefined): boolean {
  return typeof value === 'string' && value.startsWith(`${PREFIX}.`);
}

/** Encrypt a secret for storage. */
async function sealSecret(plaintext: string): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, await masterKey(), enc.encode(plaintext)));
  return `${PREFIX}.${b64(iv)}.${b64(ct)}`;
}

/** Decrypt a stored secret. Legacy plaintext is returned as-is; empty → null. Tampered → throws. */
async function openSecret(stored: string | null | undefined): Promise<string | null> {
  if (stored === null || stored === undefined) return null;
  const v = stored.trim();
  if (!v) return null;
  if (!isSealed(v)) return v; // legacy plaintext — caller should re-seal
  const [, ivB64, ctB64] = v.split('.');
  if (!ivB64 || !ctB64) throw new Error('Malformed sealed secret');
  const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, await masterKey(), unb64(ctB64));
  return dec.decode(pt);
}

/** "…abcd" for display. Never reveals more than the last 4 characters. */
function last4(plaintext: string): string {
  const t = plaintext.trim();
  return t.length <= 4 ? '' : t.slice(-4);
}

// ---- _shared/global-vars.ts ------------------------------------------------------------------
// Server-side access to tenant global variables (Phase 0 · SEC-05).
// Values of kind `secret` / `encryption_key` are sealed with MARBEE_SECRETS_KEY
// (secret-box.ts). Only edge functions (service role) can read the value column (sql/90).


type VariableScope = 'forms' | 'workflows' | 'landing_pages' | 'imports' | 'exports' | 'connectors' | 'all';

/** Plaintext of a tenant variable allowed in `scope`, or null if absent / not allowed. */
async function loadVariablePlaintext(
  svc: SupabaseClient,
  tenantId: string,
  environment: string,
  name: string,
  scope: VariableScope,
): Promise<{ kind: string; plaintext: string } | null> {
  const { data, error } = await svc.from('global_variables')
    .select('id, kind, value, scopes')
    .eq('tenant_id', tenantId).eq('environment', environment).eq('name', name)
    .maybeSingle();
  if (error || !data) return null;
  const scopes = (data.scopes as string[] | null) ?? ['all'];
  if (scope !== 'all' && !scopes.includes('all') && !scopes.includes(scope)) return null;
  const plaintext = data.kind === 'plain' ? String(data.value ?? '') : await openSecret(String(data.value ?? ''));
  if (!plaintext) return null;
  await svc.from('global_variables').update({ last_used_at: new Date().toISOString() }).eq('id', data.id);
  return { kind: String(data.kind), plaintext };
}

// ---- _shared/field-crypto.ts -----------------------------------------------------------------
// Field-level encryption with a tenant data key (Phase 0 · SEC-05).
//
// Same format the browser used (apps/web/src/lib/crypto-vault.ts), so existing data
// and logic stay compatible:
//   data key  = 32 random bytes, base64 (stored as an `encryption_key` global variable,
//               itself sealed with MARBEE_SECRETS_KEY — see secret-box.ts)
//   field     = "mbe1.<base64 iv>.<base64 ciphertext+tag>" of JSON.stringify(value)
//
// Data keys now exist only on the server: generated here, sealed at rest, used here.


const FIELD_PREFIX = 'mbe1';
const fieldEnc = new TextEncoder();
const fieldDec = new TextDecoder();

async function importKey(keyB64: string): Promise<CryptoKey> {
  const raw = unb64(keyB64);
  if (raw.length !== 32) throw new Error('Data key must be 32 bytes');
  return crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
}

function generateDataKey(): string {
  return b64(crypto.getRandomValues(new Uint8Array(32)));
}

/** "a1b2 c3d4 e5f6 0718" — first 8 bytes of SHA-256, same as the browser's keyFingerprint. */
async function dataKeyFingerprint(keyB64: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', unb64(keyB64))).slice(0, 8);
  return Array.from(digest).map((b) => b.toString(16).padStart(2, '0')).join('').replace(/(.{4})/g, '$1 ').trim();
}

function isFieldEnvelope(v: unknown): v is string {
  return typeof v === 'string' && v.startsWith(`${FIELD_PREFIX}.`) && v.split('.').length === 3;
}

async function encryptFieldsWithKey(
  data: Record<string, unknown>,
  fieldNames: string[],
  keyB64: string,
): Promise<Record<string, unknown>> {
  const out: Record<string, unknown> = { ...data };
  if (fieldNames.length === 0) return out;
  const key = await importKey(keyB64);
  for (const name of fieldNames) {
    const value = out[name];
    if (value === undefined || value === null || value === '' || isFieldEnvelope(value)) continue;
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, fieldEnc.encode(JSON.stringify(value))));
    out[name] = `${FIELD_PREFIX}.${b64(iv)}.${b64(ct)}`;
  }
  return out;
}

async function decryptFieldsWithKey(
  data: Record<string, unknown>,
  fieldNames: string[],
  keyB64: string,
): Promise<Record<string, unknown>> {
  const out: Record<string, unknown> = { ...data };
  const key = await importKey(keyB64);
  for (const name of fieldNames) {
    const value = out[name];
    if (!isFieldEnvelope(value)) continue;
    try {
      const [, ivB64, ctB64] = value.split('.');
      const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(ivB64) }, key, unb64(ctB64));
      out[name] = JSON.parse(fieldDec.decode(pt));
    } catch {
      out[name] = '[decryption failed]';
    }
  }
  return out;
}

